(() => {
  const {icon,serverLogo,sheet,toast}=UI;
  const categories=[['server','服务器与账户','server'],['playback','播放','play'],['subtitles','字幕','subtitles'],['danmaku','弹幕','danmaku'],['together','一起看','together'],['appearance','外观','palette'],['downloads','下载与离线','download'],['connections','连接与集成','globe'],['network','网络与缓存','globe'],['about','关于','info']];
  const defaults={heatmap:true,danmaku:false,remember:true,related:true,duplicate:true,overlap:true,skipIntro:true,skipCredits:false,secondary:false,ambient:true,reduceMotion:false,onlyWifi:true,ready:true,notifications:true,font:22,opacity:85,speed:1,density:60,area:50,sources:[]};
  let saved;try{saved=JSON.parse(localStorage.getItem('plezy-visual-study-settings-v2')||'null');}catch{/* Demo storage is optional. */}
  const state={...defaults,...saved};
  function save(){try{localStorage.setItem('plezy-visual-study-settings-v2',JSON.stringify(state));}catch{/* Private mode may disable storage. */}}
  const row=(label,ic,key,value='',sub='')=>`<button class="setting-row" data-setting="${key}">${key.startsWith('server-')?serverLogo(key.slice(7)):ic?icon(ic):''}<span class="setting-label"><b>${label}</b>${sub?`<small>${sub}</small>`:''}</span><span class="setting-value">${value}${icon('next')}</span></button>`;
  const toggle=(label,key,sub='')=>`<div class="setting-row"><span class="setting-label"><b>${label}</b>${sub?`<small>${sub}</small>`:''}</span><button class="sw ${state[key]?'on':''}" role="switch" aria-label="${label}" aria-checked="${!!state[key]}" data-toggle-setting="${key}"></button></div>`;
  const group=(label,content)=>`<section class="setting-group"><h4>${label}</h4>${content}</section>`;
  document.querySelectorAll('[data-settings]').forEach(root=>{
    const tv=root.classList.contains('tv');let current=tv?'danmaku':'home';
    root.innerHTML=`<div class="device-scroll">${UI.status()}<div class="settings-shell"><aside><header class="screen-heading"><h3>设置</h3></header><nav class="settings-categories" aria-label="设置分类">${categories.map(([key,label,ic])=>`<button data-category="${key}">${icon(ic)}${label}</button>`).join('')}<a href="home.html" class="setting-back" style="padding:16px 12px">${icon('back')}返回首页</a></nav></aside><main class="settings-groups"></main></div></div><nav data-app-nav></nav><div class="home-indicator"></div>`;
    UI.hydrate(root);const pane=root.querySelector('.settings-groups');
    function render(category=current){current=category;root.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));
      const heading=categories.find(c=>c[0]===category)?.[1];
      let content='';
      if(category==='home')content=`<button class="settings-profile" data-setting="server">${serverLogo(UI.currentServer())}<span style="text-align:left"><b>wines</b><small>${UI.currentServer()} · 3 台服务器</small></span>${icon('next')}</button>`+group('观看体验',row('播放','play','playback','自动')+row('字幕','subtitles','subtitles')+row('弹幕','danmaku','danmaku',state.sources.length?state.sources.length+' 个源':'未添加源'))+group('为你定制',row('一起看','together','together')+row('外观与首页','palette','appearance','跟随海报'))+group('资源与服务',row('服务器与账户','server','server','3 台')+row('下载与离线','download','downloads')+row('连接与集成','globe','connections')+row('网络与缓存','globe','network','演示偏好'))+group('应用',row('关于 Velo','info','about','2.23.1'))+'<p class="settings-footer">VELO · YOUR MEDIA, YOUR WAY</p>';
      if(category==='server')content=group('媒体服务器',['Emby','Jellyfin','Plex'].map((v,i)=>row(v,'server','server-'+v,'已连接',i?'备用媒体库':'默认媒体服务器 · 2 条线路')).join(''))+group('账户',row('添加服务器','plus','add-server')+row('当前用户','together','account','wines')+row('离线模式','download','offline','关闭'));
      if(category==='playback')content=group('播放核心',row('默认播放核心','','core','自动','根据设备选择 mpv 或 ExoPlayer')+row('硬件解码','','study-hardware','查看偏好','演示偏好 · 有效状态由实际核心确认'))+group('播放行为',toggle('自动跳过片头','skipIntro','跳过后显示撤销入口')+toggle('自动跳过片尾','skipCredits')+row('默认播放速度','','play-speed','1.0×')+row('流媒体画质','','quality','原始画质'))+group('高级',row('画面与音频','','picture','缩放 · 音画同步 · 音量增益')+row('视频增强','','enhance','Anime4K / FSR'));
      if(category==='subtitles')content=group('语言',row('首选字幕语言','','language','简体中文')+row('首选音频语言','','audio-language','原始语言'))+group('字幕显示',row('字幕样式','','subtitle-style','字号 · 描边 · 位置')+toggle('启用次字幕','secondary','在主字幕下方显示另一条字幕')+row('默认字幕延迟','','subtitle-delay','0 ms'))+group('来源',row('在线字幕','','online-subtitles','通过服务器提供')+row('加载本地字幕','','local-subtitles','SRT / ASS / PGS'));
      if(category==='danmaku')content=group('基础',toggle('显示弹幕','danmaku')+row('弹幕源','','sources',state.sources.length?state.sources.length+' 个源':'添加','由你添加兼容的弹弹play v2 网关')+toggle('进度条热力图','heatmap','在进度条上显示弹幕密度'))+group('匹配',toggle('记住每季匹配结果','remember')+toggle('合并关联弹幕','related')+row('繁简转换','','convert','转简体')+row('时间偏移','','offset','0 秒'))+group('显示与过滤',row('样式与密度','','danmaku-style',state.font+'px · '+state.opacity+'%')+row('屏蔽词','','blocked','0 个')+toggle('合并重复弹幕','duplicate')+toggle('防止弹幕重叠','overlap'));
      if(category==='together')content=group('连接',row('中继服务器','globe','relay','未配置','填写自己的中继地址')+row('显示名称','together','nickname','wines'))+group('房间',toggle('加入后需要准备','ready')+toggle('成员加入提醒','notifications'))+'<p class="sheet-description" style="padding:0 17px">房间通过邀请加入。播放中的同步状态显示在播放器内。</p>';
      if(category==='appearance')content=group('页面氛围',toggle('跟随当前海报取色','ambient','首页与详情使用当前媒体的色彩')+row('界面主题','palette','theme',AppTheme.label())+toggle('减少动态效果','reduceMotion','关闭海报与背景过渡'))+group('首页与布局',row('首页显示内容','','home-content','继续观看 · 最近添加')+row('媒体库海报密度','','density','标准 · 三列')+row('文字大小','','text-size','跟随系统')+row('启动页面','','startup','首页'));
      if(category==='downloads')content=group('下载',toggle('仅在 Wi-Fi 下下载','onlyWifi')+row('下载画质','','download-quality','原始画质')+row('存储位置','','storage','设备内部空间'))+group('离线媒体',row('管理下载','','manage-downloads','暂无下载')+row('自动同步规则','','sync-rules','0 条规则'));
      if(category==='connections')content=group('内容服务',row('Trakt','','integration-Trakt','未连接')+row('Seerr','','integration-Seerr','未连接')+row('AniList / MyAnimeList','','integration-Anime','未连接'))+group('设备',row('手机遥控 TV','tv','remote','配对设备')+row('网络与缓存','globe','network','演示偏好'));
      if(category==='about')content=group('Velo',row('应用版本','info','version','2.23.1 · 本地 fork')+row('开源许可','','licenses','GPL-3.0')+row('日志与诊断','','logs','导出日志'))+'<p class="sheet-description" style="padding:0 17px">此处为视觉与交互示意。连接、文件操作与播放不会由 HTML 原型执行。</p>';
      pane.innerHTML=(category!=='home'&&!tv?`<button class="setting-back" data-back style="margin-left:17px">${icon('back')}设置</button><h3 style="font-size:20px;font-weight:600;margin:0 17px 21px">${heading}</h3>`:'')+content;
      if(category==='network')PrototypeStudy.renderNetwork(root,pane);
      pane.querySelector('[data-back]')?.addEventListener('click',()=>render('home'));
      pane.querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>action(b.dataset.setting));
      pane.querySelectorAll('[data-toggle-setting]').forEach(b=>b.onclick=()=>{
        const key=b.dataset.toggleSetting;
        if(key==='danmaku'&&!state.sources.length&&!state.danmaku){sourceList(true);return;}
        state[key]=!state[key];save();b.classList.toggle('on',state[key]);b.setAttribute('aria-checked',String(state[key]));
      });
    }
    function sourceList(first=false){
      const body=`<p>${first?'先添加弹幕源，即可开始匹配与显示弹幕。':'弹幕源由你添加，不内置地址。可在名称与地址后保留所需路径前缀。'}</p>${state.sources.length?state.sources.map((s,i)=>`<div class="connection-card"><b data-source-title="${i}"></b><p data-source-address="${i}" style="overflow-wrap:anywhere"></p><div class="sheet-actions"><button class="btn sec" data-source-up="${i}" ${i===0?'disabled':''}>上移</button><button class="btn sec" data-source-remove="${i}">删除</button></div></div>`).join(''):'<div class="connection-card"><b>还没有弹幕源</b><p>添加你使用的网关地址</p></div>'}<button class="btn pri" data-add-source style="width:100%">${icon('plus')}添加弹幕源</button>`;
      sheet(root,'弹幕源',body,(s,close)=>{state.sources.forEach((v,i)=>{s.querySelector(`[data-source-title="${i}"]`).textContent=v.name;s.querySelector(`[data-source-address="${i}"]`).textContent=v.url;});s.querySelector('[data-add-source]').onclick=()=>addSource(first);s.querySelectorAll('[data-source-remove]').forEach(b=>b.onclick=()=>{state.sources.splice(Number(b.dataset.sourceRemove),1);save();close();sourceList();render();});s.querySelectorAll('[data-source-up]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.sourceUp);[state.sources[i-1],state.sources[i]]=[state.sources[i],state.sources[i-1]];save();close();sourceList();});});
    }
    function addSource(enable=false){sheet(root,'添加弹幕源',`<p>填写自己的兼容网关地址。支持 HTTPS、局域网地址与路径前缀。</p><form data-source-form><label>名称<input name="source-name" maxlength="40" placeholder="例如：家用网关" required></label><label>地址<input name="source-url" type="url" placeholder="https://你的网关地址/路径" required></label><p data-source-message role="status" style="margin-top:12px">原型只校验地址格式，不发送网络请求。</p><div class="sheet-actions"><button class="btn sec" type="button" data-test-source>检查格式</button><button class="btn pri" type="submit">保存</button></div></form>`,(s,close)=>{
      const form=s.querySelector('form'),message=s.querySelector('[data-source-message]');
      const validate=()=>{try{const url=new URL(form.elements['source-url'].value);if(!['http:','https:'].includes(url.protocol))throw Error();if(['127.0.0.1','localhost','[::1]'].includes(url.hostname)){message.textContent='这是本机地址，手机上请改用网关所在设备的地址。';return false;}message.textContent='地址格式正确 · 尚未测试真实连接';return true;}catch{message.textContent='请输入完整的 HTTP 或 HTTPS 地址。';return false;}};
      s.querySelector('[data-test-source]').onclick=validate;form.onsubmit=e=>{e.preventDefault();if(!validate())return;state.sources.push({name:form.elements['source-name'].value.trim(),url:form.elements['source-url'].value});if(enable)state.danmaku=true;save();close();render();toast(root,'已保存弹幕源（原型本地）',{type:'success'});};
    });}
    function choices(title,values,initial=0){sheet(root,title,values.map((v,i)=>`<button class="choice-row ${i===initial?'selected':''}" data-choice="${i}"><span class="choice-text"><b>${v}</b></span>${i===initial?icon('check'):''}</button>`).join(''),(s,close)=>s.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{close();toast(root,'已选择 '+values[Number(b.dataset.choice)]+'（演示）');}));}
    function action(key){
      if(key==='study-hardware'){PrototypeStudy.hardware(root);return;}
      if(categories.some(c=>c[0]===key)){render(key);return;}
      if(key==='theme'){sheet(root,'界面主题',`<p>选择跟随系统，或固定使用浅色、深色外观。</p>${['system','light','dark'].map(value=>`<button class="choice-row ${AppTheme.getMode()===value?'selected':''}" data-theme-choice="${value}"><span class="choice-text"><b>${AppTheme.labels[value]}</b>${value==='system'?'<small>随系统外观自动切换</small>':''}</span>${AppTheme.getMode()===value?icon('check'):''}</button>`).join('')}`,(s,close)=>s.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{AppTheme.setMode(b.dataset.themeChoice);close();}));return;}
      if(key==='sources'){sourceList();return;}
      if(key==='core'){sheet(root,'默认播放核心',`<p>自动使用当前设备支持的核心。</p>${['自动','mpv','ExoPlayer'].map((v,i)=>`<button class="choice-row ${i===0?'selected':''}" data-core="${v}"><span class="choice-text"><b>${v}</b><small>${i===0?'按设备与媒体选择':i===1?'完整播放器能力':'Android 系统播放路径'}</small></span>${i===0?icon('check'):''}</button>`).join('')}<div class="choice-row" style="opacity:.4"><span class="choice-text"><b>VLC · 2.0 播放核心</b><small>规划中 · 蓝光 / ISO 可选后端</small></span></div>`,(s,close)=>s.querySelectorAll('[data-core]').forEach(b=>b.onclick=()=>{close();toast(root,'选择 '+b.dataset.core+'（演示）');}));return;}
      if(key==='danmaku-style'){sheet(root,'弹幕样式与密度',`<p>以下调整保存在此浏览器的原型设置中。</p>${[['字号','font',14,36,1,'px'],['不透明度','opacity',20,100,5,'%'],['速度','speed',.5,2,.1,'×'],['同屏上限','density',10,120,10,'条'],['显示区域','area',25,100,25,'%']].map(([name,k,min,max,step,unit])=>`<label>${name}<div class="range-control"><input type="range" data-range="${k}" min="${min}" max="${max}" step="${step}" value="${state[k]}" aria-label="${name}"><output data-value="${k}">${state[k]}${unit}</output></div></label>`).join('')}<div style="background:#14171b;padding:20px;border-radius:13px;margin:18px 0;text-align:center"><span data-dm-preview style="font-size:${state.font}px;opacity:${state.opacity/100}">好故事，一起看</span></div>`,s=>s.querySelectorAll('[data-range]').forEach(n=>n.oninput=()=>{state[n.dataset.range]=Number(n.value);save();const unit={font:'px',opacity:'%',speed:'×',density:'条',area:'%'}[n.dataset.range];s.querySelector(`[data-value="${n.dataset.range}"]`).textContent=n.value+unit;s.querySelector('[data-dm-preview]').style.fontSize=state.font+'px';s.querySelector('[data-dm-preview]').style.opacity=state.opacity/100;}));return;}
      if(key==='add-server'){sheet(root,'添加媒体服务器',`<p>选择服务类型，再填写服务器地址。</p><form data-server-form><label>类型<select><option>Emby</option><option>Jellyfin</option><option>Plex</option></select></label><label>服务器地址<input type="url" placeholder="https://你的服务器地址" required></label><label>用户名<input placeholder="用户名" required></label><label>密码<input type="password" placeholder="密码"></label><button class="btn pri" type="submit" style="width:100%;margin-top:15px">连接</button></form>`,(s,close)=>s.querySelector('form').onsubmit=e=>{e.preventDefault();close();toast(root,'连接流程演示 · 未发送凭据');});return;}
      if(key.startsWith('server-')){const name=key.slice(7);sheet(root,name,`<div class="connection-card"><b><span class="server-state"></span>已连接</b><p>当前账户：wines</p><p>演示连接 · 线路策略尚未设置</p></div><button class="choice-row" data-line>管理备用线路<span class="spacer"></span>${icon('next')}</button><button class="choice-row" data-switch-account>切换账户<span class="spacer"></span>${icon('next')}</button>`,s=>{s.querySelector('[data-line]').onclick=()=>PrototypeStudy.routes(root,name);s.querySelector('[data-switch-account]').onclick=()=>choices('切换账户',['wines','家庭账户']);});return;}
      if(['relay','nickname','blocked'].includes(key)){sheet(root,{relay:'中继服务器',nickname:'显示名称',blocked:'屏蔽词'}[key],`<p>${key==='relay'?'填写自己的 WebSocket 中继地址。':'修改后仅保存在此原型中。'}</p><label>${key==='relay'?'地址':'内容'}<input placeholder="${key==='relay'?'wss://你的中继地址':key==='nickname'?'wines':'多个词用逗号分隔'}"></label><button class="btn pri" data-dismiss style="width:100%;margin-top:15px">保存</button>`);return;}
      const values={'play-speed':['0.75×','1.0×','1.25×','1.5×','2.0×'],quality:['原始画质','1080p · 20 Mbps','720p · 8 Mbps'],language:['简体中文','繁体中文','英语','日语'],'audio-language':['原始语言','普通话','英语','日语'],convert:['保持原样','转简体','转繁体'],offset:['−5 秒','−1 秒','0 秒','+1 秒','+5 秒'],'text-size':['跟随系统','标准','大号'],startup:['首页','媒体库','一起看'],density:['紧凑 · 四列','标准 · 三列','舒适 · 两列'],'home-content':['继续观看 + 最近添加','仅继续观看','仅最近添加'],'download-quality':['原始画质','1080p','720p'],offline:['关闭','开启'],account:['wines','家庭账户'],'subtitle-delay':['−500 ms','0 ms','+500 ms']};
      if(values[key]){choices(pane.querySelector(`[data-setting="${key}"] .setting-label b`)?.textContent||'选择',values[key]);return;}
      const information={picture:['画面与音频','视频缩放、音画同步与音量增益在播放器中调整，可按剧集记忆。'],enhance:['视频增强','Anime4K / FSR 由播放核心和设备能力决定。'], 'subtitle-style':['字幕样式','字幕字号、描边和垂直位置可在播放器中预览调整。'],'online-subtitles':['在线字幕','使用媒体服务器提供的字幕搜索与下载能力。'],'local-subtitles':['本地字幕','播放中选择字幕文件，支持的格式随核心而定。'],storage:['存储位置','设备内部空间 · 可用 18.2 GB（示例）'],'manage-downloads':['下载管理','暂无下载。可在详情页“更多”菜单中添加。'],'sync-rules':['自动同步规则','暂无规则。可为已关注剧集保留最近未观看集数。'],remote:['手机遥控 TV','在手机和 TV 登录同一服务器后配对设备。此处不发起真实配对。'],network:['网络与缓存','自动选择可用线路。连接缓存与播放缓存由设备管理。'],version:['Velo 本地 fork','版本 2.23.1 · 视觉原型 V2'],licenses:['开源许可','Velo · GPL-3.0。完整依赖许可在实际应用中查看。'],logs:['日志与诊断','原型不生成应用日志。']};
      const [title,text]=information[key]||[key.startsWith('integration-')?'连接 '+key.slice(12):'设置详情','在实际应用中配置此服务。原型用于确认入口位置。'];sheet(root,title,`<p>${text}</p><button class="btn sec" data-dismiss style="width:100%">知道了</button>`);
    }
    window.addEventListener('appearancechange',()=>{const value=pane.querySelector('[data-setting="theme"] .setting-value');if(value)value.innerHTML=AppTheme.label()+icon('next');});
    root.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>render(b.dataset.category));render();
  });
})();
